tip.code:
label { transition: translate .3s, scale .3s; transition-timing-function: cubic-bezier(.2, 0, 0, 1); }
input:not(:placeholder-shown) + label { translate: 0 -22px; scale: .7; }
.count { height: 1lh; overflow: hidden; }
.digits { transition: translate .4s cubic-bezier(.34, 1.56, .64, 1); }
.new .digits { translate: 0 -1lh; }
.sheet { translate: 0 100%; transition: translate .6s linear(0, 1.08 40%, .98 65%, 1); }
.open .sheet { translate: 0; }
